"""Authoring source for the hand-written, offline Arena Serial catalogue.

Run this file to regenerate the adjacent inspectable JSON stories. Branches and
consequences are authored below; this does not generate dialogue with an LLM.
"""
from __future__ import annotations

import json
from pathlib import Path


def L(speaker, text, emotion=None):
    result = {"speaker": speaker, "text": text}
    if emotion:
        result["emotion"] = emotion
    return result


def F(t=0, g=0, c=0, e=0):
    return dict(trust=t, goal=g, control=c, eq=e)


def O(key, text, reaction, effects, flags, explanation, requires=None):
    result = dict(id=key, text=text, reaction=reaction, effects=effects,
                  flags=flags, explanation=explanation)
    if requires:
        result["requires"] = requires
    return result


def S(key, background, dialogue, options):
    return dict(id=key, background=background, dialogue=dialogue, options=options)


def E(key, title, text, reflection, when=None):
    return dict(id=key, title=title, text=text, reflection=reflection, when=when)


def authored_order(stage):
    """Keep choice positions varied and reproducible in the authored catalogue."""
    options = stage["options"]
    offset = sum(ord(character) for character in stage["id"]) % len(options)
    return options[offset:] + options[:offset]


def episode(key, title, summary, perspective, stages, endings, *,
            intro=None, premium=None, bonus=False, cost=0):
    """Expand authored stages into explicit nodes with a reaction per choice."""
    nodes = []
    first = stages[0]["id"]
    if intro:
        intro_background, intro_lines, variants = intro
        router = dict(id="opening", background=intro_background,
                      dialogue=intro_lines, next=first, branches=[])
        for index, (condition, lines) in enumerate(variants):
            node_id = f"opening_variant_{index}"
            router["branches"].append(dict(when=condition, next=node_id))
            nodes.append(dict(id=node_id, background=intro_background,
                              dialogue=lines, next=first))
        nodes.insert(0, router)
        start = "opening"
    else:
        start = first

    all_stages = list(stages)
    after_core = "extra_invitation" if premium else "resolution"
    for index, stage in enumerate(all_stages):
        following = stages[index + 1]["id"] if index + 1 < len(stages) else after_core
        node = {field: stage[field] for field in ("id", "background", "dialogue")}
        node["choices"] = []
        for option in authored_order(stage):
            reaction_id = stage["id"] + "_" + option["id"] + "_reaction"
            choice = {field: option[field] for field in
                      ("id", "text", "effects", "flags", "explanation")}
            if "requires" in option:
                choice["requires"] = option["requires"]
            choice.update(next=reaction_id, cost=0)
            node["choices"].append(choice)
            nodes.append(dict(id=reaction_id, background=stage["background"],
                              dialogue=option["reaction"], next=following))
        nodes.append(node)

    if premium:
        invitation, extra_stages = premium
        invitation = dict(invitation)
        invitation.update(id="extra_invitation")
        invitation["choices"] = [
            dict(id="continue", text=invitation.pop("skip"), next="resolution",
                 effects=F(), flags={}, cost=0,
                 explanation="Основная история продолжается; все её развязки доступны без этой сцены."),
            dict(id="extra", text=invitation.pop("accept"), next=extra_stages[0]["id"],
                 effects=F(), flags={}, cost=3,
                 explanation=invitation.pop("description")),
        ]
        nodes.append(invitation)
        for index, stage in enumerate(extra_stages):
            following = extra_stages[index + 1]["id"] if index + 1 < len(extra_stages) else "resolution"
            node = {field: stage[field] for field in ("id", "background", "dialogue")}
            node["choices"] = []
            for option in authored_order(stage):
                reaction_id = stage["id"] + "_" + option["id"] + "_reaction"
                choice = {field: option[field] for field in
                          ("id", "text", "effects", "flags", "explanation")}
                choice.update(next=reaction_id, cost=0)
                node["choices"].append(choice)
                nodes.append(dict(id=reaction_id, background=stage["background"],
                                  dialogue=option["reaction"], next=following))
            nodes.append(node)

    background = stages[-1]["background"]
    resolution = dict(id="resolution", background=background,
                      dialogue=[L("narrator", "Разговор окончен. Договорённости остаются с вами."),
                                L("narrator", "Некоторые последствия станут заметны только при следующей встрече.")],
                      branches=[], next="ending_" + endings[-1]["id"])
    for ending in endings:
        node_id = "ending_" + ending["id"]
        if ending.get("when"):
            resolution["branches"].append(dict(when=ending["when"], next=node_id))
        content = {field: ending[field] for field in ("id", "title", "text", "reflection")}
        nodes.append(dict(id=node_id, background=background,
                          dialogue=[L("narrator", ending["title"]), L("narrator", ending["text"])],
                          ending=content))
    nodes.append(resolution)
    return dict(id=key, title=title, summary=summary, perspective=perspective,
                bonus=bonus, cost=cost, start=start, nodes=nodes)


def P(background, dialogue, skip, accept, description, stages):
    return (dict(background=background, dialogue=dialogue, skip=skip,
                 accept=accept, description=description), stages)


def C(key, name, role, portrait):
    return dict(id=key, name=name, role=role, portrait=portrait)


def with_other_perspective(story, character_id, protagonist_portrait=0):
    """In bonus scenes 'you' always denotes the current playable character."""
    story["characters"].append(C("protagonist", "Ваш первый герой", "Персонаж основного прохождения", protagonist_portrait))
    for chapter in story["episodes"]:
        if not chapter.get("bonus"):
            continue
        for node in chapter["nodes"]:
            for line in node["dialogue"]:
                if line["speaker"] == "you":
                    line["speaker"] = "protagonist"
                elif line["speaker"] == character_id:
                    line["speaker"] = "you"
    return story


